<?php require_once __DIR__.'/../lib/db.php';session_start();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{$s=db()->prepare('SELECT * FROM admins WHERE username=? AND is_active=1');$s->execute([trim($_POST['username'])]);$u=$s->fetch();if(!$u||!password_verify($_POST['password'],$u['password_hash']))throw new Exception('로그인 정보가 올바르지 않습니다.');$_SESSION['admin']=['id'=>(int)$u['id'],'name'=>$u['name'],'role'=>$u['role'],'employee_id'=>(int)($u['employee_id']??0)];db()->prepare('UPDATE admins SET last_login=NOW() WHERE id=?')->execute([$u['id']]);header('Location: dashboard.php');exit;}catch(Throwable $e){$err=$e->getMessage();}}?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/style.css"><title>관리자 로그인</title></head><body><div class="login"><div class="card"><h1>관리자·결재자 로그인</h1><p class="muted">권한에 따라 조회 가능한 메뉴와 부서가 자동으로 제한됩니다.</p><?php if($err):?><div class="alert err"><?=h($err)?></div><?php endif?><form method="post"><label>아이디<input name="username" required></label><label>비밀번호<input type="password" name="password" required></label><button class="btn">로그인</button></form></div></div></body></html>